-- Edel Solingen: SKUs das pinças laqueadas (PIN-LAQ-PF/PO/PR) e fotos
UPDATE "products" SET "sku" = 'PIN-LAQ-PF', "updatedAt" = now()
 WHERE "sku" = 'PIN-004' AND NOT EXISTS (SELECT 1 FROM "products" WHERE "sku" = 'PIN-LAQ-PF');
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'edel-pinca-laqueada-ponta-fina.webp', 'image/webp', 2924, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'edel-pinca-laqueada-ponta-fina.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'edel-pinca-laqueada-ponta-fina.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'PIN-LAQ-PF' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
